public class DocumentWorkflowTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        DocumentWorkflow doc = new DocumentWorkflow();
        check("a new document starts as a draft", "draft", doc.state());
        doc.approve();
        check("approving a draft changes nothing", "draft", doc.state());
        check("no transition was counted", 0, doc.transitions());

        doc.submit();
        check("a submitted draft is in review", "review", doc.state());
        doc.submit();
        check("submitting again while in review", "review", doc.state());
        check("transitions after one real change", 1, doc.transitions());

        doc.reject();
        check("a rejected document is a draft again", "draft", doc.state());
        check("rejections counted", 1, doc.rejections());

        doc.submit();
        doc.approve();
        check("an approved review is published", "published", doc.state());
        check("transitions over the whole run", 4, doc.transitions());

        doc.reject();
        doc.submit();
        doc.approve();
        check("published is final", "published", doc.state());
        check("no extra transitions after publishing", 4, doc.transitions());
        check("no extra rejections after publishing", 1, doc.rejections());

        DocumentWorkflow other = new DocumentWorkflow();
        check("workflows are independent", "draft", other.state());
        check("a fresh workflow has no transitions", 0, other.transitions());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

