interface DocState {

    String label();

    DocState onSubmit();

    DocState onApprove();

    DocState onReject();
}

public class DocumentWorkflow {

    static class Draft implements DocState {
        @Override
        public String label() {
            return "draft";
        }

        @Override
        public DocState onSubmit() {
            return new Review();
        }

        @Override
        public DocState onApprove() {
            return this;
        }

        @Override
        public DocState onReject() {
            return this;
        }
    }

    static class Review implements DocState {
        @Override
        public String label() {
            return "review";
        }

        @Override
        public DocState onSubmit() {
            return this;
        }

        @Override
        public DocState onApprove() {
            return new Published();
        }

        @Override
        public DocState onReject() {
            return new Draft();
        }
    }

    static class Published implements DocState {
        @Override
        public String label() {
            return "published";
        }

        @Override
        public DocState onSubmit() {
            return this;
        }

        @Override
        public DocState onApprove() {
            return this;
        }

        @Override
        public DocState onReject() {
            return this;
        }
    }

    private DocState current = new Draft();
    private int transitions;
    private int rejections;

    public String state() {
        return current.label();
    }

    public void submit() {
        moveTo(current.onSubmit(), false);
    }

    public void approve() {
        moveTo(current.onApprove(), false);
    }

    public void reject() {
        moveTo(current.onReject(), true);
    }

    private void moveTo(DocState next, boolean rejection) {
        if (next != current) {
            current = next;
            transitions++;
            if (rejection) {
                rejections++;
            }
        }
    }

    public int transitions() {
        return transitions;
    }

    public int rejections() {
        return rejections;
    }
}
